         << DatePlus1.Day << "/" << DatePlus1.Month << "/" << DatePlus1.Year << "\n";

    cout << "02-Adding 10 days is: "
         << DatePlus10.Day << "/" << DatePlus10.Month << "/" << DatePlus10.Year << "\n";

    return 0;
}
