    short days[12] = { 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 };
    return (Month == 2) ? (isLeapYear(Year) ? 29 : 28) : days[Month - 1];
}

bool IsItLastDayInMonth(sDate Date)
{
    return (Date.Day == NumberOfDaysInAMonth(Date.Month, Date.Year));
}


bool IsLastMonthInYear(short Month)
{
    return (Month == 12);
}

sDate IncreaseDateByOneDay(sDate Date)
{
    if (IsItLastDayInMonth(Date))
    {
        Date.Day = 1;
        if (IsLastMonthInYear(Date.Month))
        {
            Date.Month = 1;
            Date.Year++;
        }
        else
        {
            Date.Month++;
        }
    }
    else
    {
        Date.Day++;
    }
    return Date;
}

sDate IncreaseDateByXDays (short XDays, sDate Date)
{
    for (int i = 0; i < XDays; i++)
    {
        Date = IncreaseDateByOneDay(Date);
    }
    return Date;
}

sDate IncreaseDateByXWeeks (short XWeeks, sDate Date)
{
    return IncreaseDateByXDays(7 * XWeeks, Date);
}


sDate IncreaseDateByOneMonth(sDate Date)
{
    if (Date.Month == 12)
    {
        Date.Month = 1;
        Date.Year++;
    }
    else
    {
        Date.Month++;
    }

    short NumberOfDaysInCurrentMonth = NumberOfDaysInAMonth(Date.Month, Date.Year);
    if (Date.Day > NumberOfDaysInCurrentMonth)
    {
        Date.Day = NumberOfDaysInCurrentMonth;
    }
    return Date;
}


sDate IncreaseDateByXMonths (short XMonths,sDate Date)
{
    for (short i = 1; i <= XMonths; i++)
    {
        Date = IncreaseDateByOneMonth(Date);
    }
    return Date;
}


sDate IncreaseDateByOneYear(sDate Date)
{
    Date.Year++;
    return Date;
}

sDate IncreaseDateByXYears(short XYears, sDate Date)
{
    for (short i = 1; i <= XYears; i++)
    {
        Date = IncreaseDateByOneYear(Date);
    }
    return Date;
}

sDate IncreaseDateByXYearsFaster(short XYears, sDate Date)
{
    Date.Year += XYears;
    return Date;
}


//The slowest soultion from abu hadhud, it duplicate the things and hard to edite
sDate IncreaseDateByOneDecade(short XDecades, sDate Date)
{
    Date.Year += XDecades * 10;
    return Date;
}

//The slowest soultion from abu hadhud
sDate IncreaseDateByXDecades(short Decade, sDate Date)
{
    for (short i = 1; i <= Decade * 10; i++)
    {
        Date = IncreaseDateByOneYear(Date);
    }
    return Date;
}
//This is my best soultion, it use Wrapper and O(1)
sDate IncreaseDateByDecadesFaster(short XDecades, sDate Date)
{
    return IncreaseDateByXYearsFaster(10*XDecades, Date);
}


sDate IncreaseDateByOneCentury(short XCentury, sDate Date)
{
    return IncreaseDateByXYearsFaster(100*XCentury, Date);
}

sDate IncreaseDateByOneMillennium(short XMillennium, sDate Date)
{
    return IncreaseDateByXYearsFaster(1000*XMillennium, Date);
}

void PrintAllDates()
{
    sDate Date = ReadFullDate();
    cout << "\nDate After: \n" << endl;

    Date = IncreaseDateByOneDay(Date);
    cout << "01-Adding one day is: "
        << Date.Day << "/" << Date.Month << "/" << Date.Year << "\n";

    Date = IncreaseDateByXDays(10, Date);
    cout << "02-Adding 10 days is: " << Date.Day << "/" << Date.Month << "/" << Date.Year << "\n";

    Date = IncreaseDateByXWeeks(1, Date);
    cout << "03-Adding one week is: " << Date.Day << "/" << Date.Month << "/" << Date.Year << "\n";

    Date = IncreaseDateByXWeeks(10, Date);
    cout << "04-Adding 10 weeks is:" << Date.Day << "/" << Date.Month << "/" << Date.Year << "\n";

    Date = IncreaseDateByXMonths(1, Date);
    cout << "05-Adding one month is: " << Date.Day << "/" << Date.Month << "/" << Date.Year << "\n";

    Date = IncreaseDateByXMonths(5, Date);
    cout << "06-Adding 5 months is: " << Date.Day << "/" << Date.Month << "/" << Date.Year << "\n";

    Date = IncreaseDateByOneYear(Date);
    cout << "07-Adding one year is: " << Date.Day << "/" << Date.Month << "/" << Date.Year << "\n";

    Date = IncreaseDateByXYears(10, Date);
    cout << "08-Adding 10 years is: " << Date.Day << "/" << Date.Month << "/" << Date.Year << "\n";

    Date = IncreaseDateByXYearsFaster(10, Date);
