            GoBackToMainMenue();
            break;

        case enMainMenueOptions::eDeleteClient:
            Util::ClearScreen();
            if (CheckAccessPermission(UserLib::enPermissions::pDeleteClient))
                ClientLib::ShowDeleteClientScreen();
            else
                ShowAccessDeniedMessage();
            GoBackToMainMenue();
            break;

        case enMainMenueOptions::eUpdateClient:
            Util::ClearScreen();
            if (CheckAccessPermission(UserLib::enPermissions::pUpdateClients))
                ClientLib::ShowUpdateClientScreen();
            else
                ShowAccessDeniedMessage();
            GoBackToMainMenue();
            break;

        case enMainMenueOptions::eFindClient:
            Util::ClearScreen();
            if (CheckAccessPermission(UserLib::enPermissions::pFindClient))
                ClientLib::ShowFindClientScreen();
            else
                ShowAccessDeniedMessage();
            GoBackToMainMenue();
            break;

        case enMainMenueOptions::eShowTransactionsMenue:
            Util::ClearScreen();
            if (CheckAccessPermission(UserLib::enPermissions::pTranactions))
                ClientLib::ShowTransactionsMenue();
            else {
                ShowAccessDeniedMessage();
                GoBackToMainMenue();
            }
            break;

        case enMainMenueOptions::eManageUsers:
            Util::ClearScreen();
            if (CheckAccessPermission(UserLib::enPermissions::pManageUsers))
                UserLib::ShowManageUsersMenue();
            else {
                ShowAccessDeniedMessage();
                GoBackToMainMenue();
            }
            break;

        case enMainMenueOptions::eExit:
            Util::ClearScreen();
            Login();
            break;
    }
}

void ShowMainMenue() {
    Util::ClearScreen();
    cout << "===========================================\n";
    cout << "\t\tMain Menue Screen\n";
    cout << "===========================================\n";
    cout << "\t[1] Show Client List.\n";
    cout << "\t[2] Add New Client.\n";
    cout << "\t[3] Delete Client.\n";
    cout << "\t[4] Update Client Info.\n";
    cout << "\t[5] Find Client.\n";
    cout << "\t[6] Transactions.\n";
    cout << "\t[7] Manage Users.\n";
    cout << "\t[8] Logout.\n";
    cout << "===========================================\n";
    PerfromMainMenueOption((enMainMenueOptions)ReadMainMenueOption());
}

bool FindUserByUserNameAndPassword(string UserName, string Password, sUser& User) {
    vector<sUser> vUsers = UserLib::LoadUsersDataFromFile(UserLib::UsersFileName);
    for (sUser U : vUsers) {
        if (U.UserName == UserName && U.Password == Password) {
            User = U;
            return true;
        }
    }
    return false;
}

void Login() {
    bool LoginFailed = false;
    string UserName, Password;

    do {
        Util::ClearScreen();
        cout << "-----------------------------------\n";
        cout << "\tLogin Screen";
        cout << "\n-----------------------------------\n";

        if (LoginFailed) {
            cout << "Invalid Username/Password!\n";
        }

        cout << "Enter Username? ";
        cin >> UserName;

        cout << "Enter Password? ";
        cin >> Password;

        LoginFailed = !FindUserByUserNameAndPassword(UserName, Password, CurrentUser);
    } while (LoginFailed);

    ShowMainMenue();
}

namespace ClientLib {
    void ShowMainMenue() { ::ShowMainMenue(); }
    void GoBackToMainMenue() { ::GoBackToMainMenue(); }
}

namespace UserLib {
    void ShowMainMenue() { ::ShowMainMenue(); }
}

int main() {
    Login();
    return 0;
}
```

### What this gives you
- A proper **login screen**
- Repeated prompts until credentials are correct
- A logged-in user stored in `CurrentUser`
- **Logout** back to login screen
- Menu access controlled by user permissions

### One small note
Your `UserLib` already stores:
- `UserName`
- `Password`
- `Permissions`

So this login screen fits your current design nicely.

If you want, I can also help you add:
- **password masking**
- **lockout after 3 failed attempts**
- **"remember last user"**
- **better separation so login is moved into `UserLib`**

```c/c++
#include "ClientLib.h"
#include <fstream>
#include <iomanip>
#include <iostream>

namespace ClientLib {
    // Forward declarations
    void ShowMainMenue();
    void GoBackToMainMenue();
    void GoBackToTransactionsMenue();

    sClient ConvertLinetoRecord(const string& Line, const string& Seperator) {
        sClient Client;
        vector<string> vClientData = Util::SplitString(Line, Seperator);
        Client.AccountNumber = vClientData[0];
        Client.PinCode = vClientData[1];
        Client.Name = vClientData[2];
        Client.Phone = vClientData[3];
        Client.AccountBalance = stod(vClientData[4]);
        return Client;
    }

    string ConvertRecordToLine(const sClient& Client, const string& Seperator) {
        string stClientRecord = "";
        stClientRecord += Client.AccountNumber + Seperator;
        stClientRecord += Client.PinCode + Seperator;
        stClientRecord += Client.Name + Seperator;
        stClientRecord += Client.Phone + Seperator;
        stClientRecord += to_string(Client.AccountBalance);
        return stClientRecord;
    }

    vector<sClient> LoadClientsDataFromFile(const string& FileName) {
        vector<sClient> vClients;
        fstream MyFile;
        MyFile.open(FileName, ios::in);
        if (MyFile.is_open()) {
            string Line;
            while (getline(MyFile, Line)) {
                if (Line != "") {
                    vClients.push_back(ConvertLinetoRecord(Line));
                }
            }
            MyFile.close();
        }
        return vClients;
    }

    void SaveClientsDataToFile(const string& FileName, const vector<sClient>& vClients) {
        fstream MyFile;
        MyFile.open(FileName, ios::out);
        if (MyFile.is_open()) {
            for (sClient C : vClients) {
                if (!C.MarkForDelete) {
                    MyFile << ConvertRecordToLine(C) << endl;
                }
            }
            MyFile.close();
        }
    }

    bool ClientExistsByAccountNumber(const string& AccountNumber, const string& FileName) {
        fstream MyFile;
        MyFile.open(FileName, ios::in);
        if (MyFile.is_open()) {
            string Line;
            while (getline(MyFile, Line)) {
                sClient Client = ConvertLinetoRecord(Line);
                if (Client.AccountNumber == AccountNumber) {
                    MyFile.close();
                    return true;
                }
            }
            MyFile.close();
        }
        return false;
    }

    bool FindClientByAccountNumber(const string& AccountNumber, const vector<sClient>& vClients, sClient& Client) {
        for (sClient C : vClients) {
            if (C.AccountNumber == AccountNumber) {
                Client = C;
                return true;
            }
        }
        return false;
    }

    void PrintClientRecordLine(const sClient& Client) {
        cout << "| " << setw(15) << left << Client.AccountNumber;
        cout << "| " << setw(10) << left << Client.PinCode;
        cout << "| " << setw(40) << left << Client.Name;
        cout << "| " << setw(12) << left << Client.Phone;
        cout << "| " << setw(12) << left << Client.AccountBalance;
    }

    void ShowAllClientsScreen() {
        vector<sClient> vClients = LoadClientsDataFromFile(ClientsFileName);
        cout << "\n\t\t\t\t\tClient List (" << vClients.size() << ") Client(s).";
        cout << "\n_______________________________________________________";
        cout << "_________________________________________\n" << endl;
        cout << "| " << left << setw(15) << "Accout Number";
        cout << "| " << left << setw(10) << "Pin Code";
        cout << "| " << left << setw(40) << "Client Name";
        cout << "| " << left << setw(12) << "Phone";
        cout << "| " << left << setw(12) << "Balance";
        cout << "\n_______________________________________________________";
        cout << "_________________________________________\n" << endl;
        if (vClients.size() == 0)
            cout << "\t\t\t\tNo Clients Available In the System!";
        else {
            for (sClient Client : vClients) {
                PrintClientRecordLine(Client);
                cout << endl;
            }
        }
        cout << "\n_______________________________________________________";
        cout << "_________________________________________\n" << endl;
    }

    sClient ReadNewClient() {
        sClient Client;
        cout << "Enter Account Number? ";
        getline(cin >> ws, Client.AccountNumber);
        while (ClientExistsByAccountNumber(Client.AccountNumber, ClientsFileName)) {
            cout << "\nClient with [" << Client.AccountNumber << "] already exists, Enter another Account Number? ";
            getline(cin >> ws, Client.AccountNumber);
        }
        cout << "Enter PinCode? "; getline(cin, Client.PinCode);
        cout << "Enter Name? "; getline(cin, Client.Name);
        cout << "Enter Phone? "; getline(cin, Client.Phone);
        cout << "Enter AccountBalance? "; cin >> Client.AccountBalance;
        return Client;
    }

    void AddNewClients() {
        char AddMore = 'Y';
        do {
            sClient Client = ReadNewClient();
            fstream MyFile;
            MyFile.open(ClientsFileName, ios::out | ios::app);
            if (MyFile.is_open()) {
                MyFile << ConvertRecordToLine(Client) << endl;
                MyFile.close();
            }
            cout << "\nClient Added Successfully, do you want to add more clients? Y/N? ";
            cin >> AddMore;
        } while (toupper(AddMore) == 'Y');
    }

    void ShowAddNewClientsScreen() {
        cout << "\n-----------------------------------\n";
        cout << "\tAdd New Clients Screen";
        cout << "\n-----------------------------------\n";
        AddNewClients();
    }

    bool MarkClientForDeleteByAccountNumber(string AccountNumber, vector<sClient>& vClients) {
        for (sClient& C : vClients) {
            if (C.AccountNumber == AccountNumber) {
                C.MarkForDelete = true;
                return true;
            }
        }
        return false;
    }

    void ShowDeleteClientScreen() {
        cout << "\n-----------------------------------\n";
        cout << "\tDelete Client Screen";
        cout << "\n-----------------------------------\n";
        string AccountNumber = "";
        cout << "\nPlease enter AccountNumber? "; cin >> AccountNumber;
        vector<sClient> vClients = LoadClientsDataFromFile(ClientsFileName);
        sClient Client;
        if (FindClientByAccountNumber(AccountNumber, vClients, Client)) {
            char Answer = 'n';
            cout << "\nAre you sure you want to delete this client y/n? "; cin >> Answer;
            if (Answer == 'y' || Answer == 'Y') {
                MarkClientForDeleteByAccountNumber(AccountNumber, vClients);
                SaveClientsDataToFile(ClientsFileName, vClients);
                cout << "\n\nClient Deleted Successfully.";
            }
        } else {
            cout << "\nClient with Account Number (" << AccountNumber << ") is Not Found!";
        }
    }

    sClient ChangeClientRecord(string AccountNumber) {
        sClient Client;
        Client.AccountNumber = AccountNumber;
        cout << "\n\nEnter PinCode? "; getline(cin >> ws, Client.PinCode);
        cout << "Enter Name? "; getline(cin, Client.Name);
        cout << "Enter Phone? "; getline(cin, Client.Phone);
        cout << "Enter AccountBalance? "; cin >> Client.AccountBalance;
        return Client;
    }

    void ShowUpdateClientScreen() {
        cout << "\n-----------------------------------\n";
        cout << "\tUpdate Client Info Screen";
        cout << "\n-----------------------------------\n";
        string AccountNumber = "";
        cout << "\nPlease enter AccountNumber? "; cin >> AccountNumber;
        vector<sClient> vClients = LoadClientsDataFromFile(ClientsFileName);
        sClient Client;
        if (FindClientByAccountNumber(AccountNumber, vClients, Client)) {
            char Answer = 'n';
            cout << "\nAre you sure you want to update this client y/n? "; cin >> Answer;
            if (Answer == 'y' || Answer == 'Y') {
                for (sClient& C : vClients) {
                    if (C.AccountNumber == AccountNumber) {
                        C = ChangeClientRecord(AccountNumber);
                        break;
                    }
                }
                SaveClientsDataToFile(ClientsFileName, vClients);
                cout << "\n\nClient Updated Successfully.";
            }
        } else {
            cout << "\nClient with Account Number (" << AccountNumber << ") is Not Found!";
        }
    }

    void PrintClientCard(const sClient& Client) {
        cout << "\nThe following are the client details:\n";
        cout << "-----------------------------------";
        cout << "\nAccount Number: " << Client.AccountNumber;
        cout << "\nPin Code      : " << Client.PinCode;
        cout << "\nName          : " << Client.Name;
        cout << "\nPhone         : " << Client.Phone;
        cout << "\nAccount Balance: " << Client.AccountBalance;
        cout << "\n-----------------------------------\n";
    }

    void ShowFindClientScreen() {
        cout << "\n-----------------------------------\n";
        cout << "\tFind Client Screen";
        cout << "\n-----------------------------------\n";
        string AccountNumber = "";
        cout << "\nPlease enter AccountNumber? "; cin >> AccountNumber;
        vector<sClient> vClients = LoadClientsDataFromFile(ClientsFileName);
        sClient Client;
        if (FindClientByAccountNumber(AccountNumber, vClients, Client)) {
            PrintClientCard(Client);
        } else {
            cout << "\nClient with Account Number (" << AccountNumber << ") is Not Found!";
        }
    }

    // Transactions
    enum enTransactionsMenueOptions { eDeposit = 1, eWithdraw = 2, eShowTotalBalance = 3, eShowMainMenue = 4 };

    void ShowDepositScreen() {
        cout << "\n-----------------------------------\n";
        cout << "\tDeposit Screen";
        cout << "\n-----------------------------------\n";
        string AccountNumber = "";
        cout << "\nPlease enter AccountNumber? "; cin >> AccountNumber;
        vector<sClient> vClients = LoadClientsDataFromFile(ClientsFileName);
        sClient Client;
        while (!FindClientByAccountNumber(AccountNumber, vClients, Client)) {
            cout << "\nClient with Account Number [" << AccountNumber << "] does not exist.\n";
            cout << "Please enter AccountNumber? "; cin >> AccountNumber;
        }
        double Amount = 0;
        cout << "\nPlease enter deposit amount? "; cin >> Amount;
        char Answer = 'n';
        cout << "\nAre you sure you want to perform this transaction? y/n? "; cin >> Answer;
        if (Answer == 'y' || Answer == 'Y') {
            for (sClient& C : vClients) {
                if (C.AccountNumber == AccountNumber) {
                    C.AccountBalance += Amount;
                    SaveClientsDataToFile(ClientsFileName, vClients);
                    cout << "\n\nDone Successfully. New balance is: " << C.AccountBalance;
                    break;
                }
            }
        }
    }

    void ShowWithDrawScreen() {
        cout << "\n-----------------------------------\n";
        cout << "\tWithdraw Screen";
        cout << "\n-----------------------------------\n";
        string AccountNumber = "";
        cout << "\nPlease enter AccountNumber? "; cin >> AccountNumber;
        vector<sClient> vClients = LoadClientsDataFromFile(ClientsFileName);
        sClient Client;
        while (!FindClientByAccountNumber(AccountNumber, vClients, Client)) {
            cout << "\nClient with Account Number [" << AccountNumber << "] does not exist.\n";
            cout << "Please enter AccountNumber? "; cin >> AccountNumber;
        }
        double Amount = 0;
        cout << "\nPlease enter withdraw amount? "; cin >> Amount;
        while (Amount > Client.AccountBalance) {
            cout << "\nAmount Exceeds the balance, you can withdraw up to : " << Client.AccountBalance << endl;
            cout << "Please enter withdraw amount? "; cin >> Amount;
        }
        char Answer = 'n';
        cout << "\nAre you sure you want to perform this transaction? y/n? "; cin >> Answer;
        if (Answer == 'y' || Answer == 'Y') {
            for (sClient& C : vClients) {
                if (C.AccountNumber == AccountNumber) {
                    C.AccountBalance -= Amount;
                    SaveClientsDataToFile(ClientsFileName, vClients);
                    cout << "\n\nDone Successfully. New balance is: " << C.AccountBalance;
                    break;
                }
            }
        }
    }

    void ShowTotalBalances() {
        vector<sClient> vClients = LoadClientsDataFromFile(ClientsFileName);
        cout << "\n\t\t\t\t\tBalances List (" << vClients.size() << ") Client(s).";
        cout << "\n_______________________________________________________";
        cout << "_________________________________________\n" << endl;
        cout << "| " << left << setw(15) << "Accout Number";
        cout << "| " << left << setw(40) << "Client Name";
        cout << "| " << left << setw(12) << "Balance";
        cout << "\n_______________________________________________________";
        cout << "_________________________________________\n" << endl;
        double TotalBalances = 0;
        if (vClients.size() == 0)
            cout << "\t\t\t\tNo Clients Available In the System!";
        else {
            for (sClient Client : vClients) {
                cout << "| " << setw(15) << left << Client.AccountNumber;
                cout << "| " << setw(40) << left << Client.Name;
                cout << "| " << setw(12) << left << Client.AccountBalance;
                cout << endl;
                TotalBalances += Client.AccountBalance;
            }
        }
        cout << "\n_______________________________________________________";
        cout << "_________________________________________\n" << endl;
        cout << "\t\t\t\t\t   Total Balances = " << TotalBalances << endl;
    }

    short ReadTransactionsMenueOption() {
        cout << "Choose what do you want to do? [1 to 4]? ";
        short Choice = 0;
        cin >> Choice;
        return Choice;
    }

    extern void ShowMainMenue();
    extern void GoBackToMainMenue();

    void PerfromTranactionsMenueOption(enTransactionsMenueOptions TransactionMenueOption) {
        switch (TransactionMenueOption) {
            case enTransactionsMenueOptions::eDeposit:
                Util::ClearScreen();
                ShowDepositScreen();
                GoBackToTransactionsMenue();
                break;
            case enTransactionsMenueOptions::eWithdraw:
                Util::ClearScreen();
                ShowWithDrawScreen();
                GoBackToTransactionsMenue();
                break;
            case enTransactionsMenueOptions::eShowTotalBalance:
                Util::ClearScreen();
                ShowTotalBalances();
                GoBackToTransactionsMenue();
                break;
            case enTransactionsMenueOptions::eShowMainMenue:
                ShowMainMenue();
                break;
        }
    }

    void ShowTransactionsMenue() {
        Util::ClearScreen();
        cout << "===========================================\n";
        cout << "\t\tTransactions Menue Screen\n";
        cout << "===========================================\n";
        cout << "\t[1] Deposit.\n";
        cout << "\t[2] Withdraw.\n";
        cout << "\t[3] Total Balances.\n";
        cout << "\t[4] Main Menue.\n";
        cout << "===========================================\n";
        PerfromTranactionsMenueOption((enTransactionsMenueOptions)ReadTransactionsMenueOption());
    }

    void GoBackToTransactionsMenue() {
        cout << "\n\nPress any key to go back to Transactions Menue...";
        Util::Pause();
        ShowTransactionsMenue();
    }
}

