            cout << "\t[2] Withdraw.\n";
            cout << "\t[3] Total Balances.\n";
            cout << "\t[4] Main Menue.\n";
            cout << "===========================================\n";

            enTransactionsMenueOptions Choice = (enTransactionsMenueOptions)ReadTransactionsMenueOption();
            switch (Choice) {
                case enTransactionsMenueOptions::eDeposit:
                    Util::ClearScreen();
                    ShowDepositScreen();
                    cout << "\n\nPress any key to go back to Transactions Menue...";
                    Util::Pause();
                    break;
                case enTransactionsMenueOptions::eWithdraw:
                    Util::ClearScreen();
                    ShowWithDrawScreen();
                    cout << "\n\nPress any key to go back to Transactions Menue...";
                    Util::Pause();
                    break;
                case enTransactionsMenueOptions::eShowTotalBalance:
                    Util::ClearScreen();
                    ShowTotalBalances();
                    cout << "\n\nPress any key to go back to Transactions Menue...";
                    Util::Pause();
                    break;
                case enTransactionsMenueOptions::eMainMenue:
                    BackToMain = true;
                    break;
            }
        }
    }
