```c/c++
#include "UserLib.h"
#include <fstream>
#include <iomanip>
#include <iostream>

namespace UserLib {
    // Prototypes for internal use
    void ShowMainMenue(); // Forward declaration if needed, but usually we use a global menu
    void GoBackToManageUsersMenue();

    sUser ConvertLinetoRecord(string Line, string Seperator) {
        sUser User;
        vector<string> vUserData = Util::SplitString(Line, Seperator);
        User.UserName = vUserData[0];
        User.Password = vUserData[1];
        User.Permissions = stoi(vUserData[2]);
        return User;
    }

    string ConvertRecordToLine(sUser User, string Seperator) {
        string stUserRecord = "";
        stUserRecord += User.UserName + Seperator;
        stUserRecord += User.Password + Seperator;
        stUserRecord += to_string(User.Permissions);
        return stUserRecord;
    }

    vector<sUser> LoadUsersDataFromFile(string FileName) {
        vector<sUser> vUsers;
        fstream MyFile;
        MyFile.open(FileName, ios::in);
        if (MyFile.is_open()) {
            string Line;
            while (getline(MyFile, Line)) {
                if (Line != "") {
                    vUsers.push_back(ConvertLinetoRecord(Line));
                }
            }
            MyFile.close();
        }
        return vUsers;
    }

    void SaveUsersDataToFile(string FileName, vector<sUser> vUsers) {
        fstream MyFile;
        MyFile.open(FileName, ios::out);
        if (MyFile.is_open()) {
            for (sUser U : vUsers) {
                if (!U.MarkForDelete) {
                    MyFile << ConvertRecordToLine(U) << endl;
                }
            }
            MyFile.close();
        }
    }

    bool UserExistsByUserName(string UserName, string FileName) {
        fstream MyFile;
        MyFile.open(FileName, ios::in);
        if (MyFile.is_open()) {
            string Line;
            while (getline(MyFile, Line)) {
                sUser User = ConvertLinetoRecord(Line);
                if (User.UserName == UserName) {
                    MyFile.close();
                    return true;
                }
            }
            MyFile.close();
        }
        return false;
    }

    bool FindUserByUserName(string UserName, vector<sUser> vUsers, sUser& User) {
        for (sUser U : vUsers) {
            if (U.UserName == UserName) {
                User = U;
                return true;
            }
        }
        return false;
    }

    void PrintUserRecordLine(sUser User) {
        cout << "| " << setw(15) << left << User.UserName;
        cout << "| " << setw(10) << left << User.Password;
        cout << "| " << setw(12) << left << User.Permissions;
    }

    void ShowAllUsersScreen() {
        vector<sUser> vUsers = LoadUsersDataFromFile(UsersFileName);
        cout << "\n\t\t\t\t\tUsers List (" << vUsers.size() << ") User(s).";
        cout << "\n_______________________________________________________";
        cout << "_________________________________________\n" << endl;
        cout << "| " << left << setw(15) << "User Name";
        cout << "| " << left << setw(10) << "Password";
        cout << "| " << left << setw(12) << "Permissions";
        cout << "\n_______________________________________________________";
        cout << "_________________________________________\n" << endl;
        if (vUsers.size() == 0)
            cout << "\t\t\t\tNo Users Available In the System!";
        else {
            for (sUser User : vUsers) {
                PrintUserRecordLine(User);
                cout << endl;
            }
        }
        cout << "\n_______________________________________________________";
        cout << "_________________________________________\n" << endl;
    }

    int ReadPermissionsToSet() {
        int Permissions = 0;
        char Answer = 'n';
        cout << "\nDo you want to give full access? y/n? ";
        cin >> Answer;
        if (Answer == 'y' || Answer == 'Y') return -1;

        cout << "\nDo you want to give access to: \n ";
        cout << "\nShow Client List? y/n? "; cin >> Answer;
        if (Answer == 'y' || Answer == 'Y') Permissions += enPermissions::pListClients;
        cout << "\nAdd New Client? y/n? "; cin >> Answer;
        if (Answer == 'y' || Answer == 'Y') Permissions += enPermissions::pAddNewClient;
        cout << "\nDelete Client? y/n? "; cin >> Answer;
        if (Answer == 'y' || Answer == 'Y') Permissions += enPermissions::pDeleteClient;
        cout << "\nUpdate Client? y/n? "; cin >> Answer;
        if (Answer == 'y' || Answer == 'Y') Permissions += enPermissions::pUpdateClients;
        cout << "\nFind Client? y/n? "; cin >> Answer;
        if (Answer == 'y' || Answer == 'Y') Permissions += enPermissions::pFindClient;
        cout << "\nTransactions? y/n? "; cin >> Answer;
        if (Answer == 'y' || Answer == 'Y') Permissions += enPermissions::pTranactions;
        cout << "\nManage Users? y/n? "; cin >> Answer;
        if (Answer == 'y' || Answer == 'Y') Permissions += enPermissions::pManageUsers;

        return Permissions;
    }

    sUser ReadNewUser() {
        sUser User;
        cout << "Enter UserName? ";
        getline(cin >> ws, User.UserName);
        while (UserExistsByUserName(User.UserName, UsersFileName)) {
            cout << "\nUser with [" << User.UserName << "] already exists, Enter another UserName? ";
            getline(cin >> ws, User.UserName);
        }
        cout << "Enter Password? "; getline(cin, User.Password);
        User.Permissions = ReadPermissionsToSet();
        return User;
    }

    void AddNewUser() {
        sUser User = ReadNewUser();
        fstream MyFile;
        MyFile.open(UsersFileName, ios::out | ios::app);
        if (MyFile.is_open()) {
            MyFile << ConvertRecordToLine(User) << endl;
            MyFile.close();
        }
    }

    void ShowAddNewUserScreen() {
        cout << "\n-----------------------------------\n";
        cout << "\tAdd New User Screen";
        cout << "\n-----------------------------------\n";
        AddNewUser();
        cout << "\nUser Added Successfully.";
    }

    bool MarkUserForDeleteByUserName(string UserName, vector<sUser>& vUsers) {
        for (sUser& U : vUsers) {
            if (U.UserName == UserName) {
                U.MarkForDelete = true;
                return true;
            }
        }
        return false;
    }

    void ShowDeleteUserScreen() {
        cout << "\n-----------------------------------\n";
        cout << "\tDelete User Screen";
        cout << "\n-----------------------------------\n";
        string UserName = "";
        cout << "\nPlease enter UserName? "; cin >> UserName;
        if (UserName == "Admin") {
            cout << "\n\nYou cannot delete this user.";
            return;
        }
        vector<sUser> vUsers = LoadUsersDataFromFile(UsersFileName);
        sUser User;
        if (FindUserByUserName(UserName, vUsers, User)) {
            char Answer = 'n';
            cout << "\nAre you sure you want to delete this user y/n? "; cin >> Answer;
            if (Answer == 'y' || Answer == 'Y') {
                MarkUserForDeleteByUserName(UserName, vUsers);
                SaveUsersDataToFile(UsersFileName, vUsers);
                cout << "\n\nUser Deleted Successfully.";
            }
        } else {
            cout << "\nUser with UserName (" << UserName << ") is Not Found!";
        }
    }

    sUser ChangeUserRecord(string UserName) {
        sUser User;
        User.UserName = UserName;
        cout << "\n\nEnter Password? "; getline(cin >> ws, User.Password);
        User.Permissions = ReadPermissionsToSet();
        return User;
    }

    void ShowUpdateUserScreen() {
        cout << "\n-----------------------------------\n";
        cout << "\tUpdate User Screen";
        cout << "\n-----------------------------------\n";
        string UserName = "";
        cout << "\nPlease enter UserName? "; cin >> UserName;
        vector<sUser> vUsers = LoadUsersDataFromFile(UsersFileName);
        sUser User;
        if (FindUserByUserName(UserName, vUsers, User)) {
            char Answer = 'n';
            cout << "\nAre you sure you want to update this user y/n? "; cin >> Answer;
            if (Answer == 'y' || Answer == 'Y') {
                for (sUser& U : vUsers) {
                    if (U.UserName == UserName) {
                        U = ChangeUserRecord(UserName);
                        break;
                    }
                }
                SaveUsersDataToFile(UsersFileName, vUsers);
                cout << "\n\nUser Updated Successfully.";
            }
        } else {
            cout << "\nUser with UserName (" << UserName << ") is Not Found!";
        }
    }

    void PrintUserCard(sUser User) {
        cout << "\nThe following are the user details:\n";
        cout << "-----------------------------------";
        cout << "\nUsername   : " << User.UserName;
        cout << "\nPassword   : " << User.Password;
        cout << "\nPermissions: " << User.Permissions;
        cout << "\n-----------------------------------\n";
    }

    void ShowFindUserScreen() {
        cout << "\n-----------------------------------\n";
        cout << "\tFind User Screen";
        cout << "\n-----------------------------------\n";
        string UserName = "";
        cout << "\nPlease enter UserName? "; cin >> UserName;
        vector<sUser> vUsers = LoadUsersDataFromFile(UsersFileName);
        sUser User;
        if (FindUserByUserName(UserName, vUsers, User)) {
            PrintUserCard(User);
        } else {
            cout << "\nUser with UserName (" << UserName << ") is Not Found!";
        }
    }

    enum enManageUsersMenueOptions {
        eListUsers = 1, eAddNewUser = 2, eDeleteUser = 3,
        eUpdateUser = 4, eFindUser = 5, eMainMenue = 6
    };

    void GoBackToManageUsersMenue() {
        cout << "\n\nPress any key to go back to Manage Users Menue...";
        Util::Pause();
        ShowManageUsersMenue();
    }

    short ReadManageUsersMenueOption() {
        cout << "Choose what do you want to do? [1 to 6]? ";
        short Choice = 0;
        cin >> Choice;
        return Choice;
    }

    // This needs to be implemented elsewhere or we need to know how to go back to Main Menu
    extern void ShowMainMenue(); 

    void PerformManageUsersMenueOption(enManageUsersMenueOptions Option) {
        switch (Option) {
            case enManageUsersMenueOptions::eListUsers:
                Util::ClearScreen();
                ShowAllUsersScreen();
                GoBackToManageUsersMenue();
                break;
            case enManageUsersMenueOptions::eAddNewUser:
                Util::ClearScreen();
                ShowAddNewUserScreen();
                GoBackToManageUsersMenue();
                break;
            case enManageUsersMenueOptions::eDeleteUser:
                Util::ClearScreen();
                ShowDeleteUserScreen();
                GoBackToManageUsersMenue();
                break;
            case enManageUsersMenueOptions::eUpdateUser:
                Util::ClearScreen();
                ShowUpdateUserScreen();
                GoBackToManageUsersMenue();
                break;
            case enManageUsersMenueOptions::eFindUser:
                Util::ClearScreen();
                ShowFindUserScreen();
                GoBackToManageUsersMenue();
                break;
            case enManageUsersMenueOptions::eMainMenue:
                ShowMainMenue();
                break;
        }
    }

    void ShowManageUsersMenue() {
        Util::ClearScreen();
        cout << "===========================================\n";
        cout << "\t\tManage Users Menue Screen\n";
        cout << "===========================================\n";
        cout << "\t[1] List Users.\n";
        cout << "\t[2] Add New User.\n";
        cout << "\t[3] Delete User.\n";
        cout << "\t[4] Update User.\n";
        cout << "\t[5] Find User.\n";
        cout << "\t[6] Main Menue.\n";
        cout << "===========================================\n";
        PerformManageUsersMenueOption((enManageUsersMenueOptions)ReadManageUsersMenueOption());
    }
}

