#include "clsBankController.h"
#include "clsClient.h"
#include "Util.h"
#include <iostream>
#include <iomanip>

using namespace std;

clsUser clsBankController::CurrentUser = clsUser("", "", "", "", 0);

void clsBankController::_ShowAccessDeniedMessage() {
    cout << "\n-----------------------------------\n";
    cout << "Access Denied, \nYou don't Have Permission To Do this,\nPlease Contact Your Admin.";
    cout << "\n-----------------------------------\n";
}

void clsBankController::_GoBackToMainMenu() {
    cout << "\n\nPress any key to go back to Main Menu...";
    Util::Pause();
}

short clsBankController::_ReadMainMenuOption() {
    cout << "Choose what do you want to do? [1 to 8]? ";
    short Choice = 0;
    cin >> Choice;
    return Choice;
}

void clsBankController::_PerformMainMenuOption(enMainMenuOptions MainMenuOption) {
    switch (MainMenuOption) {
        case enMainMenuOptions::eListClients:
            Util::ClearScreen();
            if (CurrentUser.CheckAccessPermission(clsUser::enPermissions::pListClients))
                _ShowAllClientsScreen();
            else
                _ShowAccessDeniedMessage();
            _GoBackToMainMenu();
            break;

        case enMainMenuOptions::eAddNewClient:
            Util::ClearScreen();
            if (CurrentUser.CheckAccessPermission(clsUser::enPermissions::pAddNewClient))
                _ShowAddNewClientScreen();
            else
                _ShowAccessDeniedMessage();
            _GoBackToMainMenu();
            break;

        case enMainMenuOptions::eDeleteClient:
            Util::ClearScreen();
            if (CurrentUser.CheckAccessPermission(clsUser::enPermissions::pDeleteClient))
                _ShowDeleteClientScreen();
            else
                _ShowAccessDeniedMessage();
            _GoBackToMainMenu();
            break;

        case enMainMenuOptions::eUpdateClient:
            Util::ClearScreen();
            if (CurrentUser.CheckAccessPermission(clsUser::enPermissions::pUpdateClients))
                _ShowUpdateClientScreen();
            else
                _ShowAccessDeniedMessage();
            _GoBackToMainMenu();
            break;

        case enMainMenuOptions::eFindClient:
            Util::ClearScreen();
            if (CurrentUser.CheckAccessPermission(clsUser::enPermissions::pFindClient))
                _ShowFindClientScreen();
            else
                _ShowAccessDeniedMessage();
            _GoBackToMainMenu();
            break;

        case enMainMenuOptions::eShowTransactionsMenu:
            Util::ClearScreen();
            if (CurrentUser.CheckAccessPermission(clsUser::enPermissions::pTransactions)) {
                _ShowTransactionsMenu();
            }
            else {
                _ShowAccessDeniedMessage();
                _GoBackToMainMenu();
            }
            break;

        case enMainMenuOptions::eManageUsers:
            Util::ClearScreen();
            if (CurrentUser.CheckAccessPermission(clsUser::enPermissions::pManageUsers)) {
                _ShowManageUsersMenu();
            }
            else {
                _ShowAccessDeniedMessage();
                _GoBackToMainMenu();
            }
            break;

        case enMainMenuOptions::eExit:
            break;
    }
}

void clsBankController::StartApp() {
    while (true) {
        if (!_Login()) {
            break;
        }

        bool Logout = false;
        while (!Logout) {
            Util::ClearScreen();
            cout << "===========================================\n";
            cout << "\t\tMain Menu Screen\n";
            cout << "===========================================\n";
            cout << "\t[1] Show Client List.\n";
            cout << "\t[2] Add New Client.\n";
            cout << "\t[3] Delete Client.\n";
            cout << "\t[4] Update Client Info.\n";
            cout << "\t[5] Find Client.\n";
            cout << "\t[6] Transactions.\n";
            cout << "\t[7] Manage Users.\n";
            cout << "\t[8] Logout.\n";
            cout << "===========================================\n";

            enMainMenuOptions Choice = static_cast<enMainMenuOptions>(_ReadMainMenuOption());
            if (Choice == enMainMenuOptions::eExit) {
                Logout = true;
                break;
            }
            _PerformMainMenuOption(Choice);
        }
    }
}

bool clsBankController::_Login() {
    string UserName, Password;
    short FailedLoginCount = 0;
    while (true) {
        Util::ClearScreen();
        cout << "-----------------------------------\n";
        cout << "\tLogin Screen";
        cout << "\n-----------------------------------\n";
        if (FailedLoginCount > 0) {
            cout << "Invalid Username/Password!\n";
            cout << "You have " << (3 - FailedLoginCount) << " Trials left.\n\n";
        }
        if (FailedLoginCount == 3) {
            cout << "Your are Locked after 3 faild trials \n\n";
            return false;
        }

        cout << "Enter Username? "; cin >> UserName;
        cout << "Enter Password? "; cin >> Password;

        CurrentUser = clsUser::Find(UserName, Password);
        if (!CurrentUser.IsEmpty()) {
            return true;
        } else {
            FailedLoginCount++;
        }
    }
}

// Client Screens Implementation (delegating to clsClient)
void clsBankController::_ShowAllClientsScreen() {
    vector<clsClient> vClients = clsClient::GetClientsList();
    cout << "\n\t\t\t\t\tClient List (" << vClients.size() << ") Client(s).";
    cout << "\n_______________________________________________________";
    cout << "_________________________________________\n" << endl;
    cout << "| " << left << setw(15) << "Account Number";
    cout << "| " << left << setw(10) << "Pin Code";
    cout << "| " << left << setw(40) << "Client Name";
    cout << "| " << left << setw(12) << "Phone";
    cout << "| " << left << setw(12) << "Balance";
    cout << "\n_______________________________________________________";
    cout << "_________________________________________\n" << endl;

    if (vClients.empty()) {
        cout << "\t\t\t\tNo Clients Available In the System!";
    } else {
        for (clsClient& C : vClients) {
            cout << "| " << setw(15) << left << C.GetAccountNumber();
            cout << "| " << setw(10) << left << C.GetPinCode();
            cout << "| " << setw(40) << left << C.GetName();
            cout << "| " << setw(12) << left << C.GetPhone();
            cout << "| " << setw(12) << left << C.GetAccountBalance() << endl;
        }
    }
    cout << "\n_______________________________________________________";
    cout << "_________________________________________\n" << endl;
}

void clsBankController::_ShowAddNewClientScreen() {
    cout << "\n-----------------------------------\n";
    cout << "\tAdd New Client Screen";
    cout << "\n-----------------------------------\n";

    char AddMore = 'Y';
    do {
        string AccountNumber;
        cout << "Enter Account Number? "; cin >> AccountNumber;
        while (clsClient::IsClientExist(AccountNumber)) {
            cout << "\nClient with [" << AccountNumber << "] already exists, Enter another Account Number? ";
            cin >> AccountNumber;
        }
        string PinCode, Name, Phone;
        double Balance;
        cout << "Enter PinCode? "; cin >> PinCode;
        cout << "Enter Name? "; getline(cin >> ws, Name);
        cout << "Enter Phone? "; cin >> Phone;
        cout << "Enter AccountBalance? "; cin >> Balance;

        clsClient::AddNewClient(clsClient(Name, Phone, AccountNumber, PinCode, Balance));

        cout << "\nClient Added Successfully, do you want to add more clients? Y/N? ";
        cin >> AddMore;
    } while (toupper(AddMore) == 'Y');
}

void clsBankController::_ShowDeleteClientScreen() {
    cout << "\n-----------------------------------\n";
    cout << "\tDelete Client Screen";
    cout << "\n-----------------------------------\n";
    string AccountNumber;
    cout << "\nPlease enter AccountNumber? "; cin >> AccountNumber;

    clsClient Client = clsClient::Find(AccountNumber);
    if (!Client.IsEmpty()) {
        char Answer;
        cout << "\nAre you sure you want to delete this client y/n? "; cin >> Answer;
        if (Answer == 'y' || Answer == 'Y') {
            clsClient::DeleteClient(AccountNumber);
            cout << "\n\nClient Deleted Successfully.";
        }
    } else {
        cout << "\nClient with Account Number (" << AccountNumber << ") is Not Found!";
    }
}

void clsBankController::_ShowUpdateClientScreen() {
    cout << "\n-----------------------------------\n";
    cout << "\tUpdate Client Info Screen";
    cout << "\n-----------------------------------\n";
    string AccountNumber;
    cout << "\nPlease enter AccountNumber? "; cin >> AccountNumber;

    clsClient Client = clsClient::Find(AccountNumber);
    if (!Client.IsEmpty()) {
        char Answer;
        cout << "\nAre you sure you want to update this client y/n? "; cin >> Answer;
        if (Answer == 'y' || Answer == 'Y') {
            string PinCode, Name, Phone;
            double Balance;
            cout << "\n\nEnter PinCode? "; cin >> PinCode;
            cout << "Enter Name? "; getline(cin >> ws, Name);
            cout << "Enter Phone? "; cin >> Phone;
            cout << "Enter AccountBalance? "; cin >> Balance;

            Client.SetPinCode(PinCode);
            Client.SetName(Name);
            Client.SetPhone(Phone);
            Client.SetAccountBalance(Balance);

            clsClient::UpdateClient(Client);
            cout << "\n\nClient Updated Successfully.";
        }
    } else {
        cout << "\nClient with Account Number (" << AccountNumber << ") is Not Found!";
    }
}

void clsBankController::_ShowFindClientScreen() {
    cout << "\n-----------------------------------\n";
    cout << "\tFind Client Screen";
    cout << "\n-----------------------------------\n";
    string AccountNumber;
    cout << "\nPlease enter AccountNumber? "; cin >> AccountNumber;

    clsClient Client = clsClient::Find(AccountNumber);
    if (!Client.IsEmpty()) {
        cout << "\nThe following are the client details:\n";
        cout << "-----------------------------------";
        cout << "\nAccount Number: " << Client.GetAccountNumber();
        cout << "\nPin Code      : " << Client.GetPinCode();
        cout << "\nName          : " << Client.GetName();
        cout << "\nPhone         : " << Client.GetPhone();
        cout << "\nAccount Balance: " << Client.GetAccountBalance();
        cout << "\n-----------------------------------\n";
    } else {
        cout << "\nClient with Account Number (" << AccountNumber << ") is Not Found!";
    }
}

// Transactions implementation
void clsBankController::_ShowTransactionsMenu() {
    bool BackToMain = false;
    while (!BackToMain) {
        Util::ClearScreen();
        cout << "===========================================\n";
        cout << "\t\tTransactions Menu Screen\n";
        cout << "===========================================\n";
        cout << "\t[1] Deposit.\n";
        cout << "\t[2] Withdraw.\n";
        cout << "\t[3] Total Balances.\n";
        cout << "\t[4] Main Menu.\n";
        cout << "===========================================\n";

        short Choice;
        cout << "Choose what do you want to do? [1 to 4]? "; cin >> Choice;
        enTransactionsMenuOptions Option = static_cast<enTransactionsMenuOptions>(Choice);
        if (Option == enTransactionsMenuOptions::eTransMainMenu) {
            BackToMain = true;
            break;
        }
        _PerformTransactionsMenuOption(Option);
    }
}

void clsBankController::_PerformTransactionsMenuOption(enTransactionsMenuOptions Option) {
    switch (Option) {
        case enTransactionsMenuOptions::eDeposit:
            Util::ClearScreen();
            _ShowDepositScreen();
            cout << "\n\nPress any key to go back to Transactions Menu...";
            Util::Pause();
            break;
        case enTransactionsMenuOptions::eWithdraw:
            Util::ClearScreen();
            _ShowWithDrawScreen();
            cout << "\n\nPress any key to go back to Transactions Menu...";
            Util::Pause();
            break;
        case enTransactionsMenuOptions::eShowTotalBalance:
            Util::ClearScreen();
            _ShowTotalBalances();
            cout << "\n\nPress any key to go back to Transactions Menu...";
            Util::Pause();
            break;
        case enTransactionsMenuOptions::eTransMainMenu:
            break;
    }
}

void clsBankController::_ShowDepositScreen() {
    cout << "\n-----------------------------------\n";
    cout << "\tDeposit Screen";
    cout << "\n-----------------------------------\n";
    string AccountNumber;
    cout << "\nPlease enter AccountNumber? "; cin >> AccountNumber;

    while (!clsClient::IsClientExist(AccountNumber)) {
        cout << "\nClient with Account Number [" << AccountNumber << "] does not exist.\n";
        cout << "Please enter AccountNumber? "; cin >> AccountNumber;
    }

    clsClient Client = clsClient::Find(AccountNumber);
    double Amount;
    cout << "\nPlease enter deposit amount? "; cin >> Amount;
    char Answer;
    cout << "\nAre you sure you want to perform this transaction? y/n? "; cin >> Answer;
    if (Answer == 'y' || Answer == 'Y') {
        Client.SetAccountBalance(Client.GetAccountBalance() + Amount);
        clsClient::UpdateClient(Client);
        cout << "\n\nDone Successfully. New balance is: " << Client.GetAccountBalance();
    }
}

void clsBankController::_ShowWithDrawScreen() {
    cout << "\n-----------------------------------\n";
    cout << "\tWithdraw Screen";
    cout << "\n-----------------------------------\n";
    string AccountNumber;
    cout << "\nPlease enter AccountNumber? "; cin >> AccountNumber;

    while (!clsClient::IsClientExist(AccountNumber)) {
        cout << "\nClient with Account Number [" << AccountNumber << "] does not exist.\n";
        cout << "Please enter AccountNumber? "; cin >> AccountNumber;
    }

    clsClient Client = clsClient::Find(AccountNumber);
    double Amount;
    cout << "\nPlease enter withdraw amount? "; cin >> Amount;
    while (Amount > Client.GetAccountBalance()) {
        cout << "\nAmount Exceeds the balance, you can withdraw up to : " << Client.GetAccountBalance() << endl;
        cout << "Please enter withdraw amount? "; cin >> Amount;
    }
    char Answer;
    cout << "\nAre you sure you want to perform this transaction? y/n? "; cin >> Answer;
    if (Answer == 'y' || Answer == 'Y') {
        Client.SetAccountBalance(Client.GetAccountBalance() - Amount);
        clsClient::UpdateClient(Client);
        cout << "\n\nDone Successfully. New balance is: " << Client.GetAccountBalance();
    }
}

void clsBankController::_ShowTotalBalances() {
    vector<clsClient> vClients = clsClient::GetClientsList();
    cout << "\n\t\t\t\t\tBalances List (" << vClients.size() << ") Client(s).";
    cout << "\n_______________________________________________________";
    cout << "_________________________________________\n" << endl;
    cout << "| " << left << setw(15) << "Accout Number";
    cout << "| " << left << setw(40) << "Client Name";
    cout << "| " << left << setw(12) << "Balance";
    cout << "\n_______________________________________________________";
    cout << "_________________________________________\n" << endl;
    double TotalBalances = 0;
    if (vClients.empty()) {
        cout << "\t\t\t\tNo Clients Available In the System!";
    } else {
        for (clsClient& Client : vClients) {
            cout << "| " << setw(15) << left << Client.GetAccountNumber();
            cout << "| " << setw(40) << left << Client.GetName();
            cout << "| " << setw(12) << left << Client.GetAccountBalance() << endl;
            TotalBalances += Client.GetAccountBalance();
        }
    }
    cout << "\n_______________________________________________________";
    cout << "_________________________________________\n" << endl;
    cout << "\t\t\t\t\t   Total Balances = " << TotalBalances << endl;
}

