        cout << "\nUsername   : " << User.GetUserName();
        cout << "\nPassword   : " << User.GetPassword();
        cout << "\nPermissions: " << User.GetPermissions();
        cout << "\n-----------------------------------\n";
    } else {
        cout << "\nUser with UserName (" << UserName << ") is Not Found!";
    }
}

