void clsBankController::_ShowDepositScreen() {
    cout << "\n-----------------------------------\n";
    cout << "\tDeposit Screen";
    cout << "\n-----------------------------------\n";
    string AccountNumber;
    cout << "\nPlease enter AccountNumber? "; cin >> AccountNumber;

    while (!clsClient::IsClientExist(AccountNumber)) {
        cout << "\nClient with Account Number [" << AccountNumber << "] does not exist.\n";
        cout << "Please enter AccountNumber? "; cin >> AccountNumber;
    }

    clsClient Client = clsClient::Find(AccountNumber);
    double Amount;
    cout << "\nPlease enter deposit amount? "; cin >> Amount;
    char Answer;
    cout << "\nAre you sure you want to perform this transaction? y/n? "; cin >> Answer;
    if (Answer == 'y' || Answer == 'Y') {
        Client.SetAccountBalance(Client.GetAccountBalance() + Amount);
        clsClient::UpdateClient(Client);
        cout << "\n\nDone Successfully. New balance is: " << Client.GetAccountBalance();
    }
}

void clsBankController::_ShowWithDrawScreen() {
    cout << "\n-----------------------------------\n";
    cout << "\tWithdraw Screen";
    cout << "\n-----------------------------------\n";
    string AccountNumber;
    cout << "\nPlease enter AccountNumber? "; cin >> AccountNumber;

    while (!clsClient::IsClientExist(AccountNumber)) {
        cout << "\nClient with Account Number [" << AccountNumber << "] does not exist.\n";
        cout << "Please enter AccountNumber? "; cin >> AccountNumber;
    }

    clsClient Client = clsClient::Find(AccountNumber);
    double Amount;
    cout << "\nPlease enter withdraw amount? "; cin >> Amount;
    while (Amount > Client.GetAccountBalance()) {
        cout << "\nAmount Exceeds the balance, you can withdraw up to : " << Client.GetAccountBalance() << endl;
        cout << "Please enter withdraw amount? "; cin >> Amount;
    }
    char Answer;
    cout << "\nAre you sure you want to perform this transaction? y/n? "; cin >> Answer;
    if (Answer == 'y' || Answer == 'Y') {
        Client.SetAccountBalance(Client.GetAccountBalance() - Amount);
        clsClient::UpdateClient(Client);
        cout << "\n\nDone Successfully. New balance is: " << Client.GetAccountBalance();
    }
}

void clsBankController::_ShowTotalBalances() {
    vector<clsClient> vClients = clsClient::GetClientsList();
    cout << "\n\t\t\t\t\tBalances List (" << vClients.size() << ") Client(s).";
    cout << "\n_______________________________________________________";
    cout << "_________________________________________\n" << endl;
    cout << "| " << left << setw(15) << "Accout Number";
    cout << "| " << left << setw(40) << "Client Name";
    cout << "| " << left << setw(12) << "Balance";
    cout << "\n_______________________________________________________";
    cout << "_________________________________________\n" << endl;
    double TotalBalances = 0;
    if (vClients.empty()) {
        cout << "\t\t\t\tNo Clients Available In the System!";
    } else {
        for (clsClient& Client : vClients) {
            cout << "| " << setw(15) << left << Client.GetAccountNumber();
            cout << "| " << setw(40) << left << Client.GetName();
            cout << "| " << setw(12) << left << Client.GetAccountBalance() << endl;
            TotalBalances += Client.GetAccountBalance();
        }
    }
    cout << "\n_______________________________________________________";
    cout << "_________________________________________\n" << endl;
    cout << "\t\t\t\t\t   Total Balances = " << TotalBalances << endl;
}

