short clsBankController::_ReadMainMenuOption() {
    cout << "Choose what do you want to do? [1 to 8]? ";
    short Choice = 0;
    cin >> Choice;
    return Choice;
}

void clsBankController::_PerformMainMenuOption(enMainMenuOptions MainMenuOption) {
    switch (MainMenuOption) {
        case enMainMenuOptions::eListClients:
            Util::ClearScreen();
            if (CurrentUser.CheckAccessPermission(clsUser::enPermissions::pListClients))
                _ShowAllClientsScreen();
            else
                _ShowAccessDeniedMessage();
            _GoBackToMainMenu();
            break;

        case enMainMenuOptions::eAddNewClient:
            Util::ClearScreen();
            if (CurrentUser.CheckAccessPermission(clsUser::enPermissions::pAddNewClient))
                _ShowAddNewClientScreen();
            else
                _ShowAccessDeniedMessage();
            _GoBackToMainMenu();
            break;

        case enMainMenuOptions::eDeleteClient:
            Util::ClearScreen();
            if (CurrentUser.CheckAccessPermission(clsUser::enPermissions::pDeleteClient))
                _ShowDeleteClientScreen();
            else
                _ShowAccessDeniedMessage();
            _GoBackToMainMenu();
            break;

        case enMainMenuOptions::eUpdateClient:
            Util::ClearScreen();
            if (CurrentUser.CheckAccessPermission(clsUser::enPermissions::pUpdateClients))
                _ShowUpdateClientScreen();
            else
                _ShowAccessDeniedMessage();
            _GoBackToMainMenu();
            break;

        case enMainMenuOptions::eFindClient:
            Util::ClearScreen();
            if (CurrentUser.CheckAccessPermission(clsUser::enPermissions::pFindClient))
                _ShowFindClientScreen();
            else
                _ShowAccessDeniedMessage();
            _GoBackToMainMenu();
            break;

        case enMainMenuOptions::eShowTransactionsMenu:
            Util::ClearScreen();
            if (CurrentUser.CheckAccessPermission(clsUser::enPermissions::pTransactions)) {
                _ShowTransactionsMenu();
            }
            else {
                _ShowAccessDeniedMessage();
                _GoBackToMainMenu();
            }
            break;

        case enMainMenuOptions::eManageUsers:
            Util::ClearScreen();
            if (CurrentUser.CheckAccessPermission(clsUser::enPermissions::pManageUsers)) {
                _ShowManageUsersMenu();
            }
            else {
                _ShowAccessDeniedMessage();
                _GoBackToMainMenu();
            }
            break;

        case enMainMenuOptions::eExit:
            break;
    }
}

void clsBankController::StartApp() {
    while (true) {
        if (!_Login()) {
            break;
        }

        bool Logout = false;
        while (!Logout) {
            Util::ClearScreen();
            cout << "===========================================\n";
            cout << "\t\tMain Menu Screen\n";
            cout << "===========================================\n";
            cout << "\t[1] Show Client List.\n";
            cout << "\t[2] Add New Client.\n";
            cout << "\t[3] Delete Client.\n";
            cout << "\t[4] Update Client Info.\n";
            cout << "\t[5] Find Client.\n";
            cout << "\t[6] Transactions.\n";
            cout << "\t[7] Manage Users.\n";
            cout << "\t[8] Logout.\n";
            cout << "===========================================\n";

            enMainMenuOptions Choice = static_cast<enMainMenuOptions>(_ReadMainMenuOption());
            if (Choice == enMainMenuOptions::eExit) {
                Logout = true;
                break;
            }
            _PerformMainMenuOption(Choice);
        }
    }
}

bool clsBankController::_Login() {
    string UserName, Password;
    short FailedLoginCount = 0;
    while (true) {
        Util::ClearScreen();
        cout << "-----------------------------------\n";
        cout << "\tLogin Screen";
        cout << "\n-----------------------------------\n";
        if (FailedLoginCount > 0) {
            cout << "Invalid Username/Password!\n";
            cout << "You have " << (3 - FailedLoginCount) << " Trials left.\n\n";
        }
        if (FailedLoginCount == 3) {
            cout << "Your are Locked after 3 faild trials \n\n";
            return false;
        }

        cout << "Enter Username? "; cin >> UserName;
        cout << "Enter Password? "; cin >> Password;

        CurrentUser = clsUser::Find(UserName, Password);
        if (!CurrentUser.IsEmpty()) {
            return true;
        } else {
            FailedLoginCount++;
        }
    }
}

