clsClient::clsClient(std::string Name, std::string Phone, std::string AccountNumber, std::string PinCode, double AccountBalance)
    : clsPerson(Name, Phone) {
    _AccountNumber = AccountNumber;
    _PinCode = PinCode;
    _AccountBalance = AccountBalance;
}

std::string clsClient::GetAccountNumber() const {
    return _AccountNumber;
}

void clsClient::SetPinCode(std::string PinCode) {
    _PinCode = PinCode;
}

std::string clsClient::GetPinCode() const {
    return _PinCode;
}

void clsClient::SetAccountBalance(double AccountBalance) {
    _AccountBalance = AccountBalance;
}

double clsClient::GetAccountBalance() const {
    return _AccountBalance;
}

clsClient clsClient::_ConvertLineToRecord(std::string Line, std::string Separator) {
    std::vector<std::string> vClientData = Util::SplitString(Line, Separator);
    return clsClient(vClientData[2], vClientData[3], vClientData[0], vClientData[1], std::stod(vClientData[4]));
}

std::string clsClient::_ConvertRecordToLine(const clsClient& Client, std::string Separator) {
    std::string stClientRecord = "";
    stClientRecord += Client.GetAccountNumber() + Separator;
    stClientRecord += Client.GetPinCode() + Separator;
    stClientRecord += Client.GetName() + Separator;
    stClientRecord += Client.GetPhone() + Separator;
    stClientRecord += std::to_string(Client.GetAccountBalance());
    return stClientRecord;
}

std::vector<clsClient> clsClient::_LoadClientsDataFromFile() {
    std::vector<clsClient> vClients;
    std::fstream MyFile;
    MyFile.open(CLIENTS_FILE_PATH, std::ios::in);
    if (MyFile.is_open()) {
        std::string Line;
        while (std::getline(MyFile, Line)) {
            if (Line != "") {
                vClients.push_back(_ConvertLineToRecord(Line));
            }
        }
        MyFile.close();
    }
    return vClients;
}

void clsClient::_SaveClientsDataToFile(const std::vector<clsClient>& vClients) {
    std::fstream MyFile;
    MyFile.open(CLIENTS_FILE_PATH, std::ios::out);
    if (MyFile.is_open()) {
        for (const clsClient& C : vClients) {
            if (!C.GetMarkForDelete()) {
                MyFile << _ConvertRecordToLine(C) << std::endl;
            }
        }
        MyFile.close();
    }
}

clsClient clsClient::Find(std::string AccountNumber) {
    std::vector<clsClient> vClients = _LoadClientsDataFromFile();
    for (const clsClient& C : vClients) {
        if (C.GetAccountNumber() == AccountNumber) return C;
    }
    return clsClient("", "", "", "", 0);
}

bool clsClient::IsClientExist(std::string AccountNumber) {
    std::vector<clsClient> vClients = _LoadClientsDataFromFile();
    for (const clsClient& C : vClients) {
        if (C.GetAccountNumber() == AccountNumber) return true;
    }
    return false;
}

std::vector<clsClient> clsClient::GetClientsList() {
    return _LoadClientsDataFromFile();
}

void clsClient::AddNewClient(const clsClient& Client) {
    std::fstream MyFile;
    MyFile.open(CLIENTS_FILE_PATH, std::ios::out | std::ios::app);
    if (MyFile.is_open()) {
        MyFile << _ConvertRecordToLine(Client) << std::endl;
        MyFile.close();
    }
}

void clsClient::UpdateClient(const clsClient& Client) {
    std::vector<clsClient> vClients = _LoadClientsDataFromFile();
    for (clsClient &C : vClients) {
        if (C.GetAccountNumber() == Client.GetAccountNumber()) {
            C = Client;
            break;
        }
    }
    _SaveClientsDataToFile(vClients);
}

void clsClient::DeleteClient(std::string AccountNumber) {
    std::vector<clsClient> vClients = _LoadClientsDataFromFile();
    for (clsClient &C : vClients) {
        if (C.GetAccountNumber() == AccountNumber) {
            C.MarkForDeleted();
            break;
        }
    }
    _SaveClientsDataToFile(vClients);
}

bool clsClient::IsEmpty() const {
    return _AccountNumber == "";
}

