    {
        bool isFirstLetter = true;

        for (short i = 0; i < S1.length(); i++)
        {
            if (S1[i] != ' ' && isFirstLetter)
            {
                S1[i] = tolower(S1[i]);
            }
            isFirstLetter = (S1[i] == ' ' ? true : false);
        }
        return S1;
    }

    string Lowercase_All_Letters_Of_String(string S1)
    {
        for (short i = 0; i < S1.length(); i++)
        {
            S1[i] = tolower(S1[i]);
        }
        return S1;
    }

    string Uppercase_All_Letters_Of_String(string S1)
    {
        for (short i = 0; i < S1.length(); i++)
        {
            S1[i] = toupper(S1[i]);
        }
        return S1;
    }

    char Invert_Char(char char1)
    {
        return isupper(char1) ? tolower(char1) : toupper(char1);
    }

    enum enWhat_To_Count { Capital_Letters = 0, Small_Letters = 1, All = 2};

    short Count_Letters(string s1, enWhat_To_Count what_to_count = enWhat_To_Count::All)
    {
        short count = 0;
        for (short i = 0; i < s1.length(); i++)
        {
            if (what_to_count == All && isalpha(s1[i]))
                count++;
            else if (what_to_count == Capital_Letters && isupper(s1[i]))
                count++;
            else if (what_to_count == Small_Letters && islower(s1[i]))
                count++;
        }
