    int Count_Each_Word_In_String(string Str1)
    {
        string delim = " ";
        short pos = 0;
        string sWord;
        int count = 0;
        while ((pos = Str1.find(delim)) != string::npos)
        {
            sWord = Str1.substr(0, pos);
