    vector <string> Split_String(string Str1, string delim = " ")
    {
        vector <string> vString;

        short pos = 0;
        string sWord;

        while ((pos = Str1.find(delim)) != string::npos)
        {
            sWord = Str1.substr(0, pos);
            if (sWord != "")
            {
                vString.push_back(sWord);
            }
            Str1.erase(0, pos + delim.length());
        }
        if (Str1 != "")
        {
            vString.push_back(Str1);
        }
        return vString;
    }

    string Trim_Left(string Str1)
    {
        for (short i = 0; i < Str1.length(); i++)
        {
            if (Str1[i] != ' ')
            {
                return Str1.substr(i, Str1.length() - i);
            }
        }
        return "";
    }

    string Trim_Right(string Str1)
    {
        for (short i = Str1.length() - 1; i >= 0; i--)
        {
            if (Str1[i] != ' ')
            {
                return Str1.substr(0, i + 1);
            }
        }
        return "";
    }

    string Trim(string Str1)
    {
        return Trim_Left(Trim_Right(Str1));
    }

    string Join_Strings(vector<string> vStrings, string delimiter)
    {
        string S1 = "";
        for (string& s : vStrings)
        {
            S1 = S1 + s + delimiter;
        }
        return S1.substr(0, S1.length() - delimiter.length());
    }

    string Join_Strings(string arrStrings[], short length, string delimiter)
    {
        string S1 = "";
        for (int i = 0; i < length; i++)
        {
            S1 = S1 + arrStrings[i] + delimiter;
        }
        return S1.substr(0, S1.length() - delimiter.length());
    }

    vector <string> Split_String(string S1, string Delim)
    {
        vector <string> vString;
        short pos = 0;
        string sWord;

        while ((pos = S1.find(Delim)) != string::npos)
        {
            sWord = S1.substr(0, pos);
            if (sWord != "")
            {
                vString.push_back(sWord);
            }
            S1.erase(0, pos + Delim.length());
        }
        if (S1 != "")
        {
            vString.push_back(S1);
        }
        return vString;
    }



    string Reverse_Words_In_String(string S1)
    {
        vector <string> vString;
        string S2 = "";

        vString = Split_String(S1, " ");

        vector <string>::iterator iter = vString.end();
        while (iter != vString.begin())
        {
            iter--;
            S2 += *iter + " ";
        }
        S2 = S2.substr(0, S2.length() - 1);
        return S2;
    }

    string Replace_Words_In_String(string S1, string Words_To_Replace, string Replacement_Words)
    {
        short pos = S1.find(Words_To_Replace);
        while (pos != string::npos)
        {
            S1.replace(pos, Words_To_Replace.length(), Replacement_Words);
            pos = S1.find(Words_To_Replace);
        }
        return S1;
    }

    string Replace_Words_In_String(string S1, string Words_To_Replace,
    string Replacement_Words, bool MatchCase = true)
    {
        vector <string> vString = Split_String(S1, " ");

        for (string& s : vString)
        {
            if (MatchCase)
            {
                if (s == Words_To_Replace)
                {
                    s = Replacement_Words;
                }
            }
            else
            {
                if (Lowercase_All_Letters_Of_String(s) == Lowercase_All_Letters_Of_String(Words_To_Replace))
                {
                    s = Replacement_Words;
                }
            }
        }
        return Join_Strings(vString, " ");
    }


    string RemovePunctuation(string S1)
    {
        string S2 = "";

        for (short i = 0; i < S1.length(); i++)
        {
            if (!ispunct(S1[i]))
            {
                S2 += S1[i];
            }
        }
        return S2;
    }





};




