    short pos = S1.find(Words_To_Replace);
    while (pos != string::npos)
    {
        S1.replace(pos, Words_To_Replace.length(), Replacement_Words);
        pos = S1.find(Words_To_Replace);
    }
    return S1;
}

string Replace_Words_In_String(string S1, string Words_To_Replace,
string Replacement_Words, bool MatchCase = true)
{
    vector <string> vString = Split_String(S1, " ");

    for (string& s : vString)
    {
        if (MatchCase)
        {
            if (s == Words_To_Replace)
            {
                s = Replacement_Words;
            }
        }
        else
        {
            if (Lowercase_All_Letters_Of_String(s) == Lowercase_All_Letters_Of_String(Words_To_Replace))
            {
                s = Replacement_Words;
            }
        }
    }
    return Join_Strings(vString, " ");
}


string RemovePunctuation(string S1)
{
    string S2 = "";

    for (short i = 0; i < S1.length(); i++)
    {
        if (!ispunct(S1[i]))
        {
            S2 += S1[i];
        }
    }
    return S2;
}

