			Date.Year--;
		}
		else
			Date.Month--;

		if (Date.Day > NumberOfDaysInMonth(Date.Year, Date.Month))
			Date.Day = NumberOfDaysInMonth(Date.Year, Date.Month);
		return Date;
	}
