//
// Created by imad on 5/6/26.
//

#ifndef PROJECT1L4BANKEXTENSION2_CLSFINDCLIENTSCREEN_H
#define PROJECT1L4BANKEXTENSION2_CLSFINDCLIENTSCREEN_H


#pragma once
#include <iostream>
#include "clsScreen.h"
#include "clsPerson.h"
#include "clsBankClient.h"
#include "clsInputValidate.h"

class clsFindClientScreen :protected clsScreen
{

private :
    static void _PrintClient(clsBankClient Client)
    {
        cout << "\nClient Card:";
        cout << "\n___________________";
        cout << "\nFirstName   : " << Client.GetFirstName();
        cout << "\nLastName    : " << Client.GetLastName();
        cout << "\nFull Name   : " << Client.FullName();
        cout << "\nEmail       : " << Client.GetEmail();
        cout << "\nPhone       : " << Client.GetPhone();
        cout << "\nAcc. Number : " << Client.AccountNumber();
        cout << "\nPassword    : " << Client.GetPinCode();
        cout << "\nBalance     : " << Client.GetAccountBalance();
        cout << "\n___________________\n";
    }

public:

    static void ShowFindClientScreen()
    {
        _DrawScreenHeader("\tFind Client Screen");

        string AccountNumber;
        cout << "\nPlease Enter Account Number: ";
        AccountNumber = clsInputValidate::ReadString();
        while (!clsBankClient::IsClientExist(AccountNumber))
        {
            cout << "\nAccount number is not found, choose another one: ";
            AccountNumber = clsInputValidate::ReadString();
        }

        clsBankClient Client1 = clsBankClient::Find(AccountNumber);

        if (!Client1.IsEmpty())
        {
            cout << "\nClient Found :-)\n";
        }
        else
        {
            cout << "\nClient Was not Found :-(\n";
        }
        _PrintClient(Client1);
    }
};



#endif //PROJECT1L4BANKEXTENSION2_CLSFINDCLIENTSCREEN_H
```

Because `IsClientExist(AccountNumber)` only answers **yes/no**.

After the loop finishes, you know:

> “There is a client with this account number.”

But you still don’t have the actual client object yet.

So this line:

```cpp
clsBankClient Client1 = clsBankClient::Find(AccountNumber);
```

is used to **load/get the full client data**: first name, last name, email, phone, balance, PIN code, etc.

Think of it like this:

```cpp
if (fileExists("client.txt"))
{
    // Good, it exists.
    // But we still need to open/read it to get the data.
}
```

Same idea:

```cpp
IsClientExist(AccountNumber); // checks if the client exists
Find(AccountNumber);          // returns the client object/data
```

However, in your current logic, this part becomes mostly unnecessary:

```cpp
if (!Client1.IsEmpty())
{
    cout << "\nClient Found :-)\n";
}
else
{
    cout << "\nClient Was not Found :-(\n";
}
```

Because the `while` loop already guarantees the account number exists before calling `Find`.

So you could simplify it to:

```cpp
clsBankClient Client1 = clsBankClient::Find(AccountNumber);

cout << "\nClient Found :-)\n";
_PrintClient(Client1);
```

Unless there is a chance that the data changes between `IsClientExist` and `Find`, the `IsEmpty()` check is redundant here.

A better design could be to call `Find` directly and check `IsEmpty()`, avoiding searching twice:

```cpp
clsBankClient Client1 = clsBankClient::Find(AccountNumber);

while (Client1.IsEmpty())
{
    cout << "\nAccount number is not found, choose another one: ";
    AccountNumber = clsInputValidate::ReadString();
    Client1 = clsBankClient::Find(AccountNumber);
}

cout << "\nClient Found :-)\n";
_PrintClient(Client1);
```

That way, you use `Find` both to check existence **and** get the client data in one step.

