        cout << setw(37) << left << "" << "===========================================\n";

        _PerfromMainMenueOption(static_cast<enMainMenueOptions>(_ReadMainMenueOption())
        );
    }
};

#endif // PROJECT1L4BANKEXTENSION2_CLSMAINSCREEN_H
