            MyFile.open("Clients.txt", ios::in);//read Mode

            if (MyFile.is_open())
            {
                string Line;
                while (getline(MyFile, Line))
                {
                    clsBankClient Client = _ConvertLinetoClientObject(Line);
                    if (Client.AccountNumber() == AccountNumber && Client.GetPinCode() == PinCode)
                    {
                        MyFile.close();
                        return Client;
                    }
                }

                MyFile.close();
            }
            return _GetEmptyClientObject();
        }
```

Also fix the `Save()` function so it always returns a value and does not accidentally fall through from `EmptyMode` into `UpdateMode`:

<llm-snippet-file>include/clsBankClient.h</llm-snippet-file>
```c++
        enum enSaveResults { svFaildEmptyObject = 0, svSucceeded = 1, svFaildAccountNumberExists = 2 };

        enSaveResults Save()
        {
            switch (_Mode)
            {
            case enMode::EmptyMode:
            {
                return enSaveResults::svFaildEmptyObject;
            }

            case enMode::UpdateMode:
            {
                _Update();
                return enSaveResults::svSucceeded;
            }

            case enMode::AddNewMode:
            {
                if (clsBankClient::IsClientExist(_AccountNumber))
                {
                    return enSaveResults::svFaildAccountNumberExists;
                }
                else
                {
                    _AddNew();
                    _Mode = enMode::UpdateMode;
                    return enSaveResults::svSucceeded;
                }
            }
            }

            return enSaveResults::svFaildEmptyObject;
        }
```

Finally, replace the property-style access in total balances:

<llm-snippet-file>include/clsBankClient.h</llm-snippet-file>
