            _GoBackToMainMenue();
            break;

        case enMainMenueOptions::eManageUsers:
            _ClearScreen();
            _ShowManageUsersMenue();
            _GoBackToMainMenue();
            break;

        case enMainMenueOptions::eExit:
            _ClearScreen();
            _Logout();
            break;
        }
    }

public:
    static void ShowMainMenue()
    {
