```c/c++
//
// Created by imad on 4/24/26.
//

#ifndef PROJECT1L4BANKEXTENSION2_CLSPERSON_H
#define PROJECT1L4BANKEXTENSION2_CLSPERSON_H


#pragma once
#include <iostream>
#include <string>
using namespace std;

class clsPerson
{
private:
    string _FirstName;
    string _LastName;
    string _Email;
    string _Phone;

public:
    clsPerson( string FirstName, string LastName, string Email, string Phone)
    {
        _FirstName = FirstName;
        _LastName = LastName;
        _Email = Email;
        _Phone = Phone;
    }

    string SetFirstName(string FirstName)
    {
        _FirstName = FirstName;
    }

    //Property Get
    string GetFirstName()
    {
        return _FirstName;
    }

    //Property Set
    void SetLastName(string LastName)
    {
        _LastName = LastName;
    }

    //Property Get
    string GetLastName()
    {
        return _LastName;
    }

    //Property Set
    void SetEmail(string Email)
    {
        _Email = Email;
    }

    //Property Get
    string GetEmail()
    {
        return _Email;
    }

    //Property Set
    void SetPhone(string Phone)
    {
        _Phone = Phone;
    }

    //Property Get
    string GetPhone()
    {
        return _Phone;
    }

    string FullName()
    {
        return _FirstName + " " + _LastName;
    }

    void Print()
    {
        cout << "\nInfo:";
        cout << "\n___________________";
        cout << "\nFirstName: " << _FirstName;
        cout << "\nLastName : " << _LastName;
        cout << "\nFull Name: " << FullName();
        cout << "\nEmail    : " << _Email;
        cout << "\nPhone    : " << _Phone;
        cout << "\n___________________\n";
    }
};
#endif //PROJECT1L4BANKEXTENSION2_CLSPERSON_H
```

The lists are probably showing for a moment, then they disappear immediately because you still use:

```cpp
system("pause>0");
```

On Linux this command does **not wait**, so the program immediately goes back to the menu and clears the screen.

Also, the **clients list** has another issue: `clsBankClient.h` still opens:

```cpp
"Clients.txt"
```

instead of using your CMake path:

```cpp
CLIENTS_FILE_PATH
```

So fix these two things.

